&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;THIS ROLE IS RIGHT FOR YOU IF...&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
