&lt;li&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW21389343 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21389343 BCX8&quot;&gt;Strategisches Verständnis&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW21389343 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21389343 BCX8&quot;&gt;&lt;strong&gt;: &lt;/strong&gt;Du denkst kanalübergreifend, erkennst Zusammenhänge schnell und kannst strategische Empfehlungen adressatengerecht ableiten und präsentieren.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW235946103 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;Kommunikationsstärke:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW235946103 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;&amp;nbsp;Du überzeugst durch ein souveränes Auftreten, starke Präsentationsfähigkeiten und ein hohes Maß an Empathie im Umgang mit&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW235946103 BCX8&quot;&gt;Kund:innen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;&amp;nbsp;und Teams.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW235946103 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW263049427 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263049427 BCX8&quot;&gt;Organisationstalent &amp;amp; Resilienz:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW263049427 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263049427 BCX8&quot;&gt;&amp;nbsp;Auch in dynamischen Projektphasen behältst du den Überblick, priorisierst sicher und arbeitest strukturiert sowie lösungsorientiert.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW263049427 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW263049427 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW62890311 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW62890311 BCX8&quot;&gt;Collaboration&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62890311 BCX8&quot;&gt;&amp;nbsp;Mindset:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW62890311 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW62890311 BCX8&quot;&gt;&amp;nbsp;Du arbeitest gerne mit unterschiedlichen Teams und Persönlichkeiten zusammen und verstehst dich als verbindende Kraft innerhalb komplexer&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62890311 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW62890311 BCX8&quot;&gt;Projekte.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW62890311 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW263049427 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW184853532 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW184853532 BCX8&quot;&gt;Analytisches Verständnis:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW184853532 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW184853532 BCX8&quot;&gt;&amp;nbsp;Zahlen, KPIs und datenbasierte Entscheidungen sind dir vertraut und unterstützen deine strategische Herangehensweise.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW184853532 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW263049427 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW113274042 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW113274042 BCX8&quot;&gt;Sprachtalent:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW113274042 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW113274042 BCX8&quot;&gt;&amp;nbsp;Du verfügst&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW113274042 BCX8&quot;&gt;über fließende&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW113274042 BCX8&quot;&gt;&amp;nbsp;Deutsch- und Englischkenntnisse in Wort und Schrift.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW113274042 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Darüber hinaus bist du:&lt;strong&gt;&lt;span class=&quot;TextRun SCXW43523389 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW43523389 BCX8&quot;&gt;&amp;nbsp;#kommunikationsstark #strategisch #teamorientiert #resilien&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW43523389 BCX8&quot;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW43523389 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Wenn du diesen Job spannend findest, dann ermutigen wir dich ausdrücklich zur Bewerbung, auch wenn du nicht jede oben gelistete Qualifikation aufweisen kannst.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Arbeiten bei WPP Media:&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Als WPP Media gestalten wir die Zukunft der Medien und investieren dabei konsequent in unsere Mitarbeiter:innen. Jede:r Kolleg:in genießt die Vorteile des globalen Netzwerks von WPP Media und WPP, um sich weiterzuentwickeln&amp;nbsp;und an der Spitze von Marketing und Werbung zu lernen. Vielfalt und Zusammenhalt leben wir durch zahlreiche Employee Resource Groups und regelmäßige interne Events - zum Austausch, zur Inspiration und zum gemeinsamen Feiern unserer Erfolge.&lt;br&gt;&amp;nbsp;&lt;br&gt;WPP Media ist ein Arbeitgeber, der Chancengleichheit fördert. Wir berücksichtigen alle Bewerber:innen für alle Positionen ohne Diskriminierung. Unser Ziel ist eine Kultur des Respekts und der Zugehörigkeit, in der jede:r die gleichen Möglichkeiten hat, sich einzubringen und beruflich zu wachsen.&lt;/p&gt;
&lt;p&gt;Bitte lies unsere &lt;a href=&quot;https://www.wppmedia.com/pages/privacy-policy&quot;&gt;Datenschutzerklärung&lt;/a&gt; für Deutschland, Österreich und die Schweiz, um weitere Informationen darüber zu erhalten, wie wir die von dir bereitgestellten Daten verarbeiten.&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;Please read our &lt;a href=&quot;https://www.wppmedia.com/pages/privacy-policy#:~:text=WPP%20Media%20Privacy%20Notice%20for%20Recruitment&quot;&gt;Privacy Notice&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;for more information on how we process the information you provide.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW227196529 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About WPP Media&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP is the trusted growth partner for the world’s leading brands. With exceptional talent, trusted data and intelligence, and world-class partnerships – all united by our pioneering agentic marketing platform, WPP Open – we help clients navigate change, capture opportunity, and deliver transformational growth. &lt;/p&gt;
&lt;p&gt;WPP Media is WPP&#39;s AI-driven media operating unit, bringing together media, data, and partnerships to deliver creative personalisation at scale. Connected through WPP Open and powered by Open Intelligence, clients see exactly where, how, and why their media investment is working.&lt;/p&gt;
&lt;p&gt;For more information, visit &lt;a href=&quot;wppmedia.com&quot;&gt;wppmedia.com&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;Das bieten wir dir:&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Work-Life-Balance&lt;/strong&gt;: Mit unseren flexiblen Arbeitszeiten &amp;amp; Remote Work gestaltest du deinen Alltag so, wie er zu dir passt. Außerdem kannst du Überstunden ausgleichen.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Vacation mode on&lt;/strong&gt;: Du erhältst 30 Urlaubstage plus einen flexiblen Tag – zusätzlich sind der 24. und 31.12. frei.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Wellbeing first:&amp;nbsp;&lt;/strong&gt;Gesundheitsleistungen, attraktive Altersvorsorge sowie Mental Health Awareness Days stellen deine Gesundheit in den Mittelpunkt.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Practice makes perfect&lt;/strong&gt;: Entfalte dich mit unseren vielfältigen Weiterbildungen und nutze unsere internen Karriereprogramme für deine Entwicklung im WPP-Netzwerk.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;More than just a job&lt;/strong&gt;: Dich erwarten unvergessliche Events, Mitarbeitendenrabatte und weitere Highlights wie das Job Ticket, Wellhub oder das Job Bike.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Be yourself&lt;/strong&gt;: Bei uns ist jede:r herzlich willkommen - Vielfalt und Chancengleichheit liegen uns am Herzen.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;Das bewegst du:&lt;/h2&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;Als&amp;nbsp;&lt;strong&gt;Senior Online Marketing Strategy Manager (Mensch) &lt;/strong&gt;bist du Spezialist für Bewegtbild und bewegst dich sicher über nahezu alle digitalen Video-Kanäle hinweg. Als zentrale Ansprechperson ordnest du den Bewegtbildmarkt ein, bewertest Angebote und übersetzt Komplexität in klare nächste Schritte für Teams und Kunden.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Markt- &amp;amp; Trendanalyse:&lt;/strong&gt; Entwicklungen im Videomarkt (TV, Streaming, ATV, OLV, Social Video) verfolgst du kontinuierlich und hältst somit unsere Planungen up to date.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Chancenableitung:&lt;/strong&gt; Aus Marktbewegungen leitest du konkrete Chancen ab und gibst klar formulierte Empfehlungen so aufbereitet weiter, dass Kundenteams direkt damit arbeiten können.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Produkt- &amp;amp; Toolentwicklung:&lt;/strong&gt; Bei der Konzeption und Weiterentwicklung unserer Video-Lösungen und -Tools bringst du Struktur, Praxisnähe und neue Impulse ein.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Standards &amp;amp; Playbooks:&lt;/strong&gt; An praxisnahen Playbooks und Standards für integrierte Videoplanung arbeitest du aktiv mit und sorgst für konsistente Qualität in der Anwendung.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Projektkoordination:&lt;/strong&gt; Gemeinsam mit deiner Führungskraft koordinierst du Innovationsprojekte und stimmst dich eng mit Planning, Buying, Data/Tech und Kundenberatung ab.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Wissenstransfer &amp;amp; Auftritt:&lt;/strong&gt; Insights teilst du proaktiv mit internen Teams, unterstützt Trainings und vertrittst WPP Media bei Bedarf in Partnerterminen oder Pitches.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;Das zeichnet dich aus:&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Video-Expertise:&lt;/strong&gt; &lt;span class=&quot;TextRun SCXW94813120 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;Du bringst ein&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;breites&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;V&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;erständnis des Videomarkt&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;e&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;&amp;nbsp;mit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;&amp;nbsp;und Interesse daran, dieses kontinuierlich&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;einzubringen und&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;zu vertiefen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW94813120 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW94813120 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Berufserfahrung&lt;/strong&gt;: &lt;span class=&quot;TextRun SCXW117572460 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;Mehrjährige Erfahrung im Video-Markt bringst du mit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;. Gerne&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;Erfahrung aus Kundenberatung oder&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;&amp;nbsp;P&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;lanung –&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;d&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;u weißt&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;, wie man komplexe Themen für unterschiedliche Zielgruppen aufbereitet und Menschen überzeugt&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW117572460 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW117572460 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Beratungskompetenz:&lt;/strong&gt; &lt;span class=&quot;NormalTextRun SCXW116316098 BCX0&quot;&gt;Strukturiertes Denken und die Fähigkeit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW116316098 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW116316098 BCX0&quot;&gt;klare Handlungsempfehlungen abzuleiten sind für dich selbstverständlich&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW116316098 BCX0&quot;&gt;.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW116316098 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Kommunikationsstärke: &lt;/strong&gt;&lt;span class=&quot;TextRun SCXW57055158 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW57055158 BCX0&quot;&gt;Du kannst&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW57055158 BCX0&quot;&gt;komplexe Sachverhalte verständlich machen – für erfahrene&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW57055158 BCX0&quot;&gt;Kolleg:innen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW57055158 BCX0&quot;&gt;&amp;nbsp;genauso wie für&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW57055158 BCX0&quot;&gt;Neu-&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW57055158 BCX0&quot;&gt;Einsteiger:innen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW57055158 BCX0&quot;&gt; oder Kunden.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Intrinsische Neugier:&lt;/strong&gt; Marktentwicklungen werden von dir verfolgt - nicht weil du musst, sondern weil du möchtest.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Eigeninitiative:&lt;/strong&gt; &lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;Du&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;&amp;nbsp;warte&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;t nicht darauf, dass Themen zu&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;d&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;ir&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;&amp;nbsp;kommen –&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;d&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;u&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;&amp;nbsp;geh&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;t auf sie z&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;u&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt;Dabei arbeitest du gerne&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW169912539 BCX0&quot;&gt;soweit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW169912539 BCX0&quot;&gt; selbständig, wie du kannst.&lt;/span&gt;&lt;/li&gt;
